insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('el-impacto-ambiental-de-tu-ropa','ambiente',array['industria','negocios']::text[],'El impacto ambiental de tu ropa','Revisa de qué está hecha tu ropa, cuánto se usa y qué pasa con ella al final, para descubrir qué decisiones reducen su impacto sin renunciar a vestirte.','Investigación','~22 h',22,array['Ropa','Moda']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria ambiental ingenieria textil diseno grafico quimica economia administracion comunicaciones sociologia lectura de etiquetas. investigacion de fuentes. analisis de datos. comunicacion clara. hoja de calculo. informes publicos sobre impacto textil. un editor de graficos.',$a16sld${"id": "el-impacto-ambiental-de-tu-ropa", "area": "ambiente", "areas2": ["industria", "negocios"], "titulo": "El impacto ambiental de tu ropa", "resumen": "Revisa de qué está hecha tu ropa, cuánto se usa y qué pasa con ella al final, para descubrir qué decisiones reducen su impacto sin renunciar a vestirte.", "tipo": "Investigación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Ropa", "Moda"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Textil", "Diseño Gráfico", "Química", "Economía", "Administración", "Comunicaciones", "Sociología"], "problema": ["La ropa se renueva rápido y muchas prendas se usan pocas veces antes de guardarse o desecharse. Pero producirlas requiere agua, energía y materias primas, y sus fibras sintéticas tienen su propia historia al lavarse y desecharse.", "Casi nadie sabe qué dice la etiqueta de su ropa ni cuánto la usa realmente, así que es difícil decidir qué conviene cuidar, reparar, intercambiar o comprar distinto."], "desarrollar": ["Haz un inventario de diez a quince prendas, anotando el material de la etiqueta, la antigüedad y cuántas veces las usas al mes, y agrúpalas en las que usas mucho, poco o casi nunca.", "Con información pública, resume qué impacto suele asociarse a cada tipo de fibra y qué acciones reducen el impacto, y propón tres cambios de hábito para tu propio armario."], "ampliaciones": [{"titulo": "Costo por uso", "aporta": "calcula cuánto cuesta cada uso de una prenda según su precio y cuántas veces la usas."}, {"titulo": "Cuidar para que dure", "aporta": "reúne cuidados de lavado que alargan la vida de la ropa."}, {"titulo": "Alternativas", "aporta": "compara segunda mano, intercambio, reparación y compra nueva."}], "objetivos": ["Registrar un inventario con criterios claros.", "Entender qué dicen las etiquetas de composición.", "Resumir información pública sobre fibras.", "Proponer cambios realistas."], "habilidades": ["Lectura de etiquetas.", "Investigación de fuentes.", "Análisis de datos.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Informes públicos sobre impacto textil.", "Un editor de gráficos."], "lineamientos": ["Cita las fuentes de cualquier dato de impacto y no inventes cifras; distingue claramente entre lo que investigas y lo que supones.", "No juzgues a las personas por cómo visten ni compares guardarropas ajenos."], "otroSector": "El mismo método sirve para analizar el impacto de alimentos, tecnología, muebles o cualquier categoría de consumo."}$a16sld$::jsonb,24),
('un-aparato-electronico-viejo-un-uso-nuevo','ambiente',array['tecnologia','industria']::text[],'Un aparato electrónico viejo, un uso nuevo','Elige un celular, una laptop o un aparato que ya no usas y descubre cómo darle una función nueva sin desarmarlo: como reloj, cámara fija, servidor o consola de recuerdos.','Prototipo','~25 h',25,array['Electrónica','Reutilización']::text[],array['crear','resolver']::text[],'propios',NULL,'ingenieria electronica ingenieria de sistemas ingenieria electrica ingenieria mecanica ingenieria de software educacion diseno grafico ingenieria ambiental resolucion de problemas. configuracion de dispositivos. documentacion tecnica. creatividad aplicada. un aparato en desuso. aplicaciones de uso libre. materiales de soporte reutilizados.',$a17sld${"id": "un-aparato-electronico-viejo-un-uso-nuevo", "area": "ambiente", "areas2": ["tecnologia", "industria"], "titulo": "Un aparato electrónico viejo, un uso nuevo", "resumen": "Elige un celular, una laptop o un aparato que ya no usas y descubre cómo darle una función nueva sin desarmarlo: como reloj, cámara fija, servidor o consola de recuerdos.", "tipo": "Prototipo", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Electrónica", "Reutilización"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Electrónica", "Ingeniería de Sistemas", "Ingeniería Eléctrica", "Ingeniería Mecánica", "Ingeniería de Software", "Educación", "Diseño Gráfico", "Ingeniería Ambiental"], "problema": ["Los aparatos electrónicos viejos se guardan o se desechan aunque muchos siguen funcionando: una pantalla, una cámara o una conexión útil. Se acumulan porque su uso original dejó de tener sentido.", "Reutilizarlos exige imaginar nuevas funciones y evaluar qué se puede hacer sin riesgo, y evita la compra de otro dispositivo."], "desarrollar": ["Elige un aparato que siga encendiendo sin riesgo, define una nueva función que no requiera abrirlo, como una pantalla de información, una cámara fija, un reproductor o un monitor secundario, y búscale un soporte con materiales que ya tengas.", "Configúralo para esa función, pruébalo durante unos días y documenta qué funcionó, qué limitaciones tuvo y cuánto ahorro de una compra nueva supuso."], "ampliaciones": [{"titulo": "Otro aparato, otra función", "aporta": "repite con un dispositivo distinto y compara qué usos fueron más viables."}, {"titulo": "Guía paso a paso", "aporta": "convierte el proceso en una guía para que otras personas lo reproduzcan."}, {"titulo": "Estimar el impacto", "aporta": "calcula cuánto tiempo extra de uso lograste y qué compra evitaste."}], "objetivos": ["Evaluar si un aparato es seguro de reutilizar.", "Definir una función nueva viable.", "Configurar y probar su uso.", "Documentar el proceso."], "habilidades": ["Resolución de problemas.", "Configuración de dispositivos.", "Documentación técnica.", "Creatividad aplicada."], "herramientas": ["Un aparato en desuso.", "Aplicaciones de uso libre.", "Materiales de soporte reutilizados."], "lineamientos": ["No uses aparatos con batería hinchada, dañada o que se calienten de forma anormal, y no los abras ni los perfores: si hay dudas, llévalos a un punto de acopio autorizado.", "Borra antes tus datos personales y cuentas del dispositivo, y no lo dejes cargando sin supervisión."], "otroSector": "La misma idea sirve para dar nuevos usos a equipos de un laboratorio, una oficina o un colegio."}$a17sld$::jsonb,25),
('cuanta-agua-se-pierde-por-fugas-pequenas','ambiente',array['ciudades','ciencias']::text[],'¿Cuánta agua se pierde por fugas pequeñas?','Aprende a detectar fugas pequeñas con métodos sencillos y estima cuánta agua se pierde en un mes por una gota, un goteo o un inodoro que no sella bien.','Análisis','~15 h',15,array['Agua','Fugas']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental ingenieria civil ingenieria sanitaria fisica ingenieria industrial estadistica arquitectura quimica medicion y estimacion. observacion sistematica. calculo de proyecciones. comunicacion clara. recipiente graduado y cronometro. colorante o tinte para detectar fugas en inodoros. hoja de calculo.',$a18sld${"id": "cuanta-agua-se-pierde-por-fugas-pequenas", "area": "ambiente", "areas2": ["ciudades", "ciencias"], "titulo": "¿Cuánta agua se pierde por fugas pequeñas?", "resumen": "Aprende a detectar fugas pequeñas con métodos sencillos y estima cuánta agua se pierde en un mes por una gota, un goteo o un inodoro que no sella bien.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Agua", "Fugas"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Civil", "Ingeniería Sanitaria", "Física", "Ingeniería Industrial", "Estadística", "Arquitectura", "Química"], "problema": ["Una fuga pequeña casi nunca se nota: un caño que gotea, un inodoro que corre o una conexión que suda. Como cada gota es poca cosa, se deja pasar, pero a lo largo de un mes la suma puede ser enorme.", "Detectar y medir esas pérdidas ayuda a decidir si vale la pena arreglarlas y a comprender por qué los recibos a veces suben sin que cambie el uso."], "desarrollar": ["Elige un lugar, como tu casa o un baño de tu centro de estudios con permiso, y busca posibles fugas con métodos sencillos, como revisar el medidor sin consumo, escuchar o usar colorante en la cisterna del inodoro.", "Para cada fuga encontrada, mide cuánta agua cae en un tiempo corto con un recipiente, proyéctalo a un día y a un mes, y presenta una tabla con las pérdidas y su costo aproximado."], "ampliaciones": [{"titulo": "Costo anual", "aporta": "estima cuánto dinero y cuánta agua se perderían en un año si nadie la arregla."}, {"titulo": "Revisar varios espacios", "aporta": "compara baños, cocinas y jardines y descubre dónde son más frecuentes."}, {"titulo": "Lista de revisión", "aporta": "crea una lista breve para que cualquier persona detecte fugas en su casa."}], "objetivos": ["Aprender métodos simples de detección.", "Medir y proyectar una pérdida.", "Presentar los resultados con claridad.", "Proponer qué reparar primero."], "habilidades": ["Medición y estimación.", "Observación sistemática.", "Cálculo de proyecciones.", "Comunicación clara."], "herramientas": ["Recipiente graduado y cronómetro.", "Colorante o tinte para detectar fugas en inodoros.", "Hoja de cálculo."], "lineamientos": ["No abras ni modifiques instalaciones sanitarias, válvulas ni medidores: observa y mide desde afuera.", "Si trabajas en un espacio que no es tuyo, pide permiso y informa a quien lo administra lo que encuentres."], "otroSector": "El mismo método sirve para detectar pérdidas de aire comprimido, de gas, de calor o de electricidad en una instalación."}$a18sld$::jsonb,26),
('sistema-para-detectar-y-registrar-desperdicios-de-agua-en-una-in','ambiente',array['tecnologia','ciudades']::text[],'Sistema para detectar y registrar desperdicios de agua en una institución','Diseña cómo una institución podría registrar y detectar pérdidas de agua con lecturas periódicas, alertas sencillas y un reporte comprensible.','Prototipo','3 a 5 semanas',30,array['Agua','Monitoreo']::text[],array['crear','resolver']::text[],'ficticios',NULL,'ingenieria de sistemas ingenieria civil ingenieria ambiental ingenieria electronica ingenieria industrial administracion ciencia de datos ingenieria de software diseno de sistemas de registro. analisis de datos. definicion de umbrales. visualizacion de informacion. hoja de calculo o un formulario. datos simulados. herramientas de graficos. herramientas de programacion si deseas automatizarlo.',$a19sld${"id": "sistema-para-detectar-y-registrar-desperdicios-de-agua-en-una-in", "area": "ambiente", "areas2": ["tecnologia", "ciudades"], "titulo": "Sistema para detectar y registrar desperdicios de agua en una institución", "resumen": "Diseña cómo una institución podría registrar y detectar pérdidas de agua con lecturas periódicas, alertas sencillas y un reporte comprensible.", "tipo": "Prototipo", "tiempo": "3 a 5 semanas", "horas": 30, "etiquetas": ["Agua", "Monitoreo"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Civil", "Ingeniería Ambiental", "Ingeniería Electrónica", "Ingeniería Industrial", "Administración", "Ciencia de Datos", "Ingeniería de Software"], "problema": ["En colegios, universidades u oficinas, el agua se consume a diario y rara vez se mira cuánto. Una fuga o un grifo abierto puede pasar semanas sin detectarse, y el problema solo aparece en el recibo.", "Un sistema de registro no tiene que ser sofisticado: lo importante es definir qué se mide, con qué frecuencia y qué señal indica que algo anda mal."], "desarrollar": ["Define un caso, real o inventado, con sus puntos de consumo, y diseña un sistema de registro de lecturas con una frecuencia, un formato y reglas de alerta, como un consumo nocturno superior a lo esperado.", "Prueba el sistema con datos simulados que incluyan alguna fuga, comprueba si tus reglas la detectan y presenta un reporte con gráficos y recomendaciones para quien administra."], "ampliaciones": [{"titulo": "Automatizar el registro", "aporta": "explora cómo usar sensores económicos o formularios para registrar sin intervención manual."}, {"titulo": "Alertas por mensaje", "aporta": "diseña cómo se avisaría a la persona responsable cuando algo se salga de lo normal."}, {"titulo": "Evaluar costos", "aporta": "calcula cuánto costaría implementarlo y en cuánto tiempo se compensaría."}], "objetivos": ["Definir qué se mide y cada cuánto.", "Establecer reglas claras de alerta.", "Probar el sistema con datos simulados.", "Comunicar los resultados a quien decide."], "habilidades": ["Diseño de sistemas de registro.", "Análisis de datos.", "Definición de umbrales.", "Visualización de información."], "herramientas": ["Hoja de cálculo o un formulario.", "Datos simulados.", "Herramientas de gráficos.", "Herramientas de programación si deseas automatizarlo."], "lineamientos": ["Si luego aplicas el sistema en una institución real, pide autorización y limita los datos a consumo, sin registrar a personas.", "No instales sensores en redes de agua ni manipules medidores: el prototipo debe trabajarse con datos simulados o con lecturas visibles."], "otroSector": "El mismo diseño sirve para monitorear electricidad, aire, temperatura o cualquier recurso cuyo consumo pueda registrarse con regularidad."}$a19sld$::jsonb,27),
('que-tan-eficiente-es-el-uso-del-agua-en-tu-institucion-y-sus-esp','ambiente',array['ciudades','industria']::text[],'¿Qué tan eficiente es el uso del agua en tu institución y sus espacios compartidos?','Observa cómo se usa el agua en baños, jardines y áreas comunes de un espacio compartido, detecta dónde se desperdicia y propone ajustes de bajo costo.','Análisis','~25 h',25,array['Agua','Instituciones']::text[],array['investigar','resolver','otro-sector']::text[],'propios',NULL,'ingenieria ambiental ingenieria civil ingenieria industrial administracion arquitectura estadistica educacion economia observacion sistematica. analisis de datos. diseno de propuestas. comunicacion de resultados. fichas de observacion. hoja de calculo. un editor de presentaciones.',$a20sld${"id": "que-tan-eficiente-es-el-uso-del-agua-en-tu-institucion-y-sus-esp", "area": "ambiente", "areas2": ["ciudades", "industria"], "titulo": "¿Qué tan eficiente es el uso del agua en tu institución y sus espacios compartidos?", "resumen": "Observa cómo se usa el agua en baños, jardines y áreas comunes de un espacio compartido, detecta dónde se desperdicia y propone ajustes de bajo costo.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Agua", "Instituciones"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Civil", "Ingeniería Industrial", "Administración", "Arquitectura", "Estadística", "Educación", "Economía"], "problema": ["En espacios compartidos, nadie se siente dueño del agua: un caño abierto, un riego a mediodía o un lavado excesivo se repiten sin que nadie lo note. Al no pagar directamente, el ahorro rara vez es prioridad.", "Observar con orden cómo se usa permite saber qué espacios consumen más, qué hábitos pesan y qué medidas simples podrían funcionar."], "desarrollar": ["Elige un espacio compartido al que tengas acceso, pide permiso y realiza observaciones de uso en tres lugares distintos durante varios días, registrando tipo de uso, duración aproximada y posibles desperdicios.", "Resume qué usos desperdician más, propón tres ajustes concretos, como cartel, regulador o cambio de horario de riego, y estima el ahorro posible."], "ampliaciones": [{"titulo": "Comparar espacios", "aporta": "contrasta baños, jardines y cocinas y descubre dónde hay más margen de mejora."}, {"titulo": "Campaña breve", "aporta": "diseña un mensaje para el lugar y mide si algo cambia."}, {"titulo": "Leer el consumo", "aporta": "si tienes acceso a datos de consumo, compáralos con tus observaciones."}], "objetivos": ["Planificar observaciones comparables.", "Registrar usos y desperdicios con orden.", "Identificar oportunidades de ahorro.", "Presentar propuestas respaldadas con datos."], "habilidades": ["Observación sistemática.", "Análisis de datos.", "Diseño de propuestas.", "Comunicación de resultados."], "herramientas": ["Fichas de observación.", "Hoja de cálculo.", "Un editor de presentaciones."], "lineamientos": ["Pide autorización, avisa que estás observando y registra usos y lugares, no personas.", "Presenta los resultados como oportunidades y no como culpas; si encuentras una fuga, repórtala a quien administra el lugar."], "otroSector": "La misma observación sirve para estudiar el uso de energía, impresoras, aulas, ascensores o cualquier recurso compartido."}$a20sld$::jsonb,28),
('agua-de-lluvia-cuanta-se-desaprovecha-y-como-usarla','ambiente',array['ciudades','ciencias']::text[],'Agua de lluvia: ¿cuánta se desaprovecha y cómo usarla?','Estima con datos públicos de lluvia cuánta agua cae sobre un techo o un patio y qué parte podría captarse, y evalúa si tendría sentido en tu zona.','Análisis','~20 h',20,array['Agua','Lluvia']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria civil ingenieria ambiental arquitectura geografia fisica estadistica ingenieria agricola ingenieria sanitaria busqueda de datos publicos. calculo y modelado simple. evaluacion de viabilidad. comunicacion clara. datos de un servicio meteorologico. hoja de calculo. un mapa o fotos aereas para estimar areas.',$a21sld${"id": "agua-de-lluvia-cuanta-se-desaprovecha-y-como-usarla", "area": "ambiente", "areas2": ["ciudades", "ciencias"], "titulo": "Agua de lluvia: ¿cuánta se desaprovecha y cómo usarla?", "resumen": "Estima con datos públicos de lluvia cuánta agua cae sobre un techo o un patio y qué parte podría captarse, y evalúa si tendría sentido en tu zona.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Agua", "Lluvia"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Civil", "Ingeniería Ambiental", "Arquitectura", "Geografía", "Física", "Estadística", "Ingeniería Agrícola", "Ingeniería Sanitaria"], "problema": ["La lluvia cae sobre techos y calles y se pierde en los desagües, mientras en otros momentos el agua escasea. Captarla parece sencillo, pero depende de cuánto llueve, del área de captación y de para qué se usaría.", "En zonas donde llueve poco, la idea puede tener poco sentido, y en otras es muy útil. Saberlo requiere cálculos y no solo entusiasmo."], "desarrollar": ["Elige un techo o una superficie, real o ficticia, mide o estima su área y busca en datos públicos de un servicio meteorológico la lluvia mensual de una zona, tanto de tu ciudad como de otra con más lluvia.", "Calcula cuánta agua se podría captar cada mes, qué usos tendría, como riego o limpieza, y en qué meses sería útil, y concluye si valdría la pena en cada zona."], "ampliaciones": [{"titulo": "Comparar regiones", "aporta": "calcula lo mismo para una zona de costa, sierra y selva y compara los resultados."}, {"titulo": "Tamaño del tanque", "aporta": "estima qué capacidad de almacenamiento haría falta para cubrir un uso concreto."}, {"titulo": "Costo y beneficio", "aporta": "evalúa si el ahorro compensaría la inversión."}], "objetivos": ["Obtener datos públicos de lluvia.", "Calcular el potencial de captación.", "Evaluar usos posibles.", "Concluir con criterio sobre la viabilidad."], "habilidades": ["Búsqueda de datos públicos.", "Cálculo y modelado simple.", "Evaluación de viabilidad.", "Comunicación clara."], "herramientas": ["Datos de un servicio meteorológico.", "Hoja de cálculo.", "Un mapa o fotos aéreas para estimar áreas."], "lineamientos": ["Indica de dónde proviene cada dato de lluvia y no uses agua de lluvia para consumo humano sin tratamiento adecuado.", "Si tu zona llueve muy poco, plantea el proyecto con datos de otra zona o como caso ficticio y dilo claramente."], "otroSector": "El mismo cálculo sirve para estimar el potencial de captación de otros recursos, como la radiación solar o el viento."}$a21sld$::jsonb,29),
('se-puede-reutilizar-el-agua-de-casa-de-forma-segura','ambiente',array['salud','ciudades']::text[],'¿Se puede reutilizar el agua de casa de forma segura?','Investiga qué aguas del hogar podrían reutilizarse para usos como riego o limpieza, y qué precauciones y límites recomiendan las fuentes oficiales.','Investigación','~20 h',20,array['Agua','Reutilización']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria ambiental ingenieria sanitaria quimica biologia ingenieria civil medicina arquitectura ingenieria quimica investigacion de fuentes. evaluacion de riesgos. redaccion tecnica clara. diseno de informacion. guias de organismos de salud y de agua. un editor de documentos o de infografias. hoja de calculo.',$a22sld${"id": "se-puede-reutilizar-el-agua-de-casa-de-forma-segura", "area": "ambiente", "areas2": ["salud", "ciudades"], "titulo": "¿Se puede reutilizar el agua de casa de forma segura?", "resumen": "Investiga qué aguas del hogar podrían reutilizarse para usos como riego o limpieza, y qué precauciones y límites recomiendan las fuentes oficiales.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Agua", "Reutilización"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Sanitaria", "Química", "Biología", "Ingeniería Civil", "Medicina", "Arquitectura", "Ingeniería Química"], "problema": ["En casa se usa agua que luego se descarta, como la de lavar verduras o la de enjuagar, aunque en algunos casos podría reutilizarse. Pero hacerlo mal puede generar riesgos de salud, olores o problemas en plantas.", "Por eso es importante distinguir qué agua sirve para qué y cuándo no conviene reutilizarla, en lugar de repetir consejos sin sustento."], "desarrollar": ["Con guías y documentos públicos de organismos de salud y de agua, reúne qué tipos de agua del hogar se consideran reutilizables, para qué usos y con qué cuidados, y clasifícalos según el nivel de riesgo.", "Prepara una guía de una página con ejemplos claros, qué agua no se debe reutilizar nunca y cómo reconocer cuándo parar, citando cada recomendación."], "ampliaciones": [{"titulo": "Estimar cuánto se ahorra", "aporta": "calcula cuánta agua podría reutilizarse en un hogar en un mes."}, {"titulo": "Revisar mitos", "aporta": "analiza consejos populares y comprueba cuáles tienen respaldo."}, {"titulo": "Versión para el hogar", "aporta": "crea una infografía para pegar en la cocina o el lavadero."}], "objetivos": ["Reunir información de fuentes oficiales.", "Clasificar usos según el riesgo.", "Redactar una guía clara y prudente.", "Reconocer los límites de lo que se puede recomendar."], "habilidades": ["Investigación de fuentes.", "Evaluación de riesgos.", "Redacción técnica clara.", "Diseño de información."], "herramientas": ["Guías de organismos de salud y de agua.", "Un editor de documentos o de infografías.", "Hoja de cálculo."], "lineamientos": ["No recomiendes reutilizar agua para beber, cocinar ni lavar a personas o alimentos que se comen crudos, y cita siempre la fuente de cada recomendación.", "Aclara que la guía es informativa y que, ante dudas de salud, se debe consultar a un servicio oficial."], "otroSector": "La misma investigación sirve para evaluar otros procesos de reutilización, como aceites usados, calor residual o materiales de construcción."}$a22sld$::jsonb,30),
('cuanta-agua-hay-detras-de-lo-que-consumes','ambiente',array['agricultura','industria']::text[],'¿Cuánta agua hay detrás de lo que consumes?','Descubre cuánta agua se usa para producir los alimentos y objetos que consumes cada día, desde un café hasta una polera, y qué cambia si eliges de otra manera.','Investigación','~22 h',22,array['Agua','Huella hídrica']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria ambiental ingenieria agroindustrial ingenieria industrial economia quimica estadistica administracion biologia busqueda de datos. conversion de unidades. analisis comparativo. visualizacion de informacion. bases de datos publicas de huella hidrica. hoja de calculo. un editor de graficos.',$a23sld${"id": "cuanta-agua-hay-detras-de-lo-que-consumes", "area": "ambiente", "areas2": ["agricultura", "industria"], "titulo": "¿Cuánta agua hay detrás de lo que consumes?", "resumen": "Descubre cuánta agua se usa para producir los alimentos y objetos que consumes cada día, desde un café hasta una polera, y qué cambia si eliges de otra manera.", "tipo": "Investigación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Agua", "Huella hídrica"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Ambiental", "Ingeniería Agroindustrial", "Ingeniería Industrial", "Economía", "Química", "Estadística", "Administración", "Biología"], "problema": ["El agua que usamos en casa es solo una parte del total: producir un alimento, una prenda o un aparato también requiere agua, muchas veces mucho más. A esa agua invisible se le llama huella hídrica.", "Como no se ve, casi nunca entra en las decisiones de consumo, y el problema de cuidar el agua parece limitarse al grifo."], "desarrollar": ["Elige diez a quince cosas que consumes en un día, como alimentos, bebidas y algunas prendas, y busca en fuentes públicas de huella hídrica cuánta agua suele requerir producir cada una, anotando las unidades y la fuente.", "Ordena tus datos para mostrar qué consumos concentran más agua, compara con el agua del grifo que usas en un día y propón dos o tres cambios de elección que reduzcan el total."], "ampliaciones": [{"titulo": "Comparar menús", "aporta": "compara la huella hídrica de dos menús distintos en un día."}, {"titulo": "Otras unidades", "aporta": "convierte las cifras en medidas imaginables, como baldes o botellas."}, {"titulo": "Producto local", "aporta": "investiga cómo cambia la huella según de dónde viene un alimento."}], "objetivos": ["Buscar datos de huella hídrica confiables.", "Calcular el total de un día de consumo.", "Comparar con el uso doméstico directo.", "Explicar las limitaciones de los datos."], "habilidades": ["Búsqueda de datos.", "Conversión de unidades.", "Análisis comparativo.", "Visualización de información."], "herramientas": ["Bases de datos públicas de huella hídrica.", "Hoja de cálculo.", "Un editor de gráficos."], "lineamientos": ["Indica siempre la fuente de cada cifra, porque los valores varían según el método y el lugar, y no los presentes como medidas exactas.", "No hagas juicios sobre lo que come o consume una persona: es un análisis de datos, no de hábitos ajenos."], "otroSector": "El mismo método sirve para analizar la energía, el carbono o los materiales que hay detrás de un producto o de una actividad."}$a23sld$::jsonb,31),
('una-propuesta-para-ahorrar-agua-en-tu-comunidad','ambiente',array['sociedad','ciudades']::text[],'Una propuesta para ahorrar agua en tu comunidad','Diseña un plan realista para que un barrio, un edificio o una organización reduzca su consumo de agua, con acciones, mensajes y una forma de medir si funcionó.','Plan','~25 h',25,array['Agua','Comunidad']::text[],array['resolver','crear']::text[],'ficticios',NULL,'ingenieria ambiental trabajo social ingenieria civil comunicaciones administracion sociologia educacion economia diseno de planes. analisis de costos. organizacion comunitaria. comunicacion persuasiva. hoja de calculo. un editor de presentaciones. un editor de diagramas.',$a24sld${"id": "una-propuesta-para-ahorrar-agua-en-tu-comunidad", "area": "ambiente", "areas2": ["sociedad", "ciudades"], "titulo": "Una propuesta para ahorrar agua en tu comunidad", "resumen": "Diseña un plan realista para que un barrio, un edificio o una organización reduzca su consumo de agua, con acciones, mensajes y una forma de medir si funcionó.", "tipo": "Plan", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Agua", "Comunidad"], "intencion": ["resolver", "crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Ingeniería Ambiental", "Trabajo Social", "Ingeniería Civil", "Comunicaciones", "Administración", "Sociología", "Educación", "Economía"], "problema": ["Ahorrar agua no depende solo de cada persona: también de cómo se organiza una comunidad, de qué información recibe y de qué incentivos existen. Las campañas que solo piden ahorrar rara vez cambian algo.", "Un plan serio parte de conocer cómo se usa el agua en esa comunidad, qué acciones son posibles y quién se encargará de cada una."], "desarrollar": ["Elige una comunidad, real o inventada, y describe cómo usa el agua, quiénes participan y qué problemas hay, con datos estimados de consumo y justificaciones.", "Propón un plan por etapas con tres o cuatro acciones, como revisar fugas, cambiar hábitos o instalar dispositivos sencillos, con responsables, costos aproximados y un indicador para saber si funcionó."], "ampliaciones": [{"titulo": "Mensajes y materiales", "aporta": "diseña carteles o mensajes cortos para la comunidad."}, {"titulo": "Costo y ahorro", "aporta": "calcula cuánto costaría el plan y cuánto se ahorraría en un año."}, {"titulo": "Participación", "aporta": "piensa cómo se organizaría a los vecinos para sostener el plan."}], "objetivos": ["Describir la situación de partida.", "Elegir acciones viables.", "Asignar responsables y tiempos.", "Definir cómo medir resultados."], "habilidades": ["Diseño de planes.", "Análisis de costos.", "Organización comunitaria.", "Comunicación persuasiva."], "herramientas": ["Hoja de cálculo.", "Un editor de presentaciones.", "Un editor de diagramas."], "lineamientos": ["Si lo vas a presentar a una comunidad real, hazlo con su participación y sin recoger datos personales ni de consumo de cada hogar.", "Evita prometer ahorros exactos: presenta estimaciones y explica qué las sustenta."], "otroSector": "El mismo plan sirve para organizar ahorro de energía, reducción de residuos o cuidado de espacios compartidos."}$a24sld$::jsonb,32),
('auditoria-energetica-de-tu-hogar','ambiente',array['ciudades','industria']::text[],'Auditoría energética de tu hogar','Haz un diagnóstico de cómo usa la energía tu vivienda a lo largo de un día: iluminación, aparatos, calor y frío, para descubrir dónde se va y qué se podría mejorar.','Análisis','~25 h',25,array['Energía','Hogar']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria electrica ingenieria mecanica arquitectura ingenieria ambiental ingenieria industrial fisica economia estadistica observacion y registro. calculo energetico basico. analisis comparativo. comunicacion de resultados. hoja de calculo. etiquetas de potencia de los equipos. recibo de luz sin datos personales.',$a25sld${"id": "auditoria-energetica-de-tu-hogar", "area": "ambiente", "areas2": ["ciudades", "industria"], "titulo": "Auditoría energética de tu hogar", "resumen": "Haz un diagnóstico de cómo usa la energía tu vivienda a lo largo de un día: iluminación, aparatos, calor y frío, para descubrir dónde se va y qué se podría mejorar.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Energía", "Hogar"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Eléctrica", "Ingeniería Mecánica", "Arquitectura", "Ingeniería Ambiental", "Ingeniería Industrial", "Física", "Economía", "Estadística"], "problema": ["Se sabe cuánto se paga de luz, pero casi nunca se entiende qué la consume: la vivienda como conjunto, con sus horarios, su iluminación, su orientación y sus aparatos. Un recibo no dice dónde está el desperdicio.", "Una auditoría doméstica no necesita instrumentos caros: con observación ordenada y datos de etiquetas se puede construir un buen perfil del uso de energía."], "desarrollar": ["Recorre tu vivienda y registra por cada espacio los aparatos, la iluminación, las horas de uso aproximadas y condiciones como ventanas, sombra o ventilación. Calcula el consumo diario estimado usando la potencia de cada equipo.", "Compara tu estimación con el recibo de luz, explica las diferencias y elabora una lista priorizada de cinco mejoras de bajo costo con su efecto estimado."], "ampliaciones": [{"titulo": "Perfil por horas", "aporta": "arma una gráfica de consumo a lo largo del día y descubre los picos."}, {"titulo": "Estimar el costo", "aporta": "convierte cada mejora en ahorro mensual y años de recuperación."}, {"titulo": "Comparar viviendas", "aporta": "compara tu casa con la de otra persona y busca qué la diferencia."}], "objetivos": ["Registrar aparatos y horas de uso de manera ordenada.", "Calcular el consumo estimado de una vivienda.", "Contrastar con datos reales del recibo.", "Priorizar mejoras con criterios claros."], "habilidades": ["Observación y registro.", "Cálculo energético básico.", "Análisis comparativo.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Etiquetas de potencia de los equipos.", "Recibo de luz sin datos personales."], "lineamientos": ["No abras aparatos ni tableros eléctricos, y no manipules instalaciones: trabaja con etiquetas, observación y cálculos.", "Si usas el recibo, oculta tus datos personales y usa solo los consumos."], "otroSector": "La misma auditoría sirve para analizar una oficina, un colegio, un taller o un pequeño negocio."}$a25sld$::jsonb,33),
('que-aparatos-consumen-energia-aunque-parezcan-apagados','ambiente',array['tecnologia','ciencias']::text[],'¿Qué aparatos consumen energía aunque parezcan apagados?','Descubre qué aparatos de tu casa siguen consumiendo energía en modo de espera y cuánto suman en un mes, con datos de etiquetas y mediciones simples.','Análisis','~15 h',15,array['Energía','Consumo fantasma']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria electronica ingenieria electrica fisica ingenieria de sistemas ingenieria ambiental economia estadistica educacion observacion. calculo de energia. busqueda de especificaciones. comunicacion de resultados. manuales y etiquetas de equipos. hoja de calculo. medidor enchufable de consumo, si lo tienes.',$a26sld${"id": "que-aparatos-consumen-energia-aunque-parezcan-apagados", "area": "ambiente", "areas2": ["tecnologia", "ciencias"], "titulo": "¿Qué aparatos consumen energía aunque parezcan apagados?", "resumen": "Descubre qué aparatos de tu casa siguen consumiendo energía en modo de espera y cuánto suman en un mes, con datos de etiquetas y mediciones simples.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Energía", "Consumo fantasma"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Electrónica", "Ingeniería Eléctrica", "Física", "Ingeniería de Sistemas", "Ingeniería Ambiental", "Economía", "Estadística", "Educación"], "problema": ["Muchos aparatos nunca se apagan del todo: televisores, cargadores, consolas o decodificadores mantienen luces, relojes o conexiones activas. Cada uno consume poco, pero juntos pueden sumar mucho al mes.", "Como no hay ninguna señal de que algo se está gastando, el problema es casi invisible, y por eso rara vez se corrige."], "desarrollar": ["Haz una lista de los aparatos que permanecen conectados en tu casa, identifica cuáles tienen luz, reloj o modo de espera, y busca en sus manuales o fuentes públicas cuánta potencia suelen consumir en ese estado.", "Calcula cuánta energía y dinero suman al mes, ordena los aparatos de mayor a menor y propón qué conviene desconectar y qué es mejor dejar encendido."], "ampliaciones": [{"titulo": "Medir en casa", "aporta": "si tienes un medidor enchufable de consumo, compara tu medición con los datos de fabricantes."}, {"titulo": "Solución práctica", "aporta": "prueba una regleta con interruptor y calcula el ahorro."}, {"titulo": "Cuidar la comodidad", "aporta": "identifica qué aparatos sí conviene dejar conectados y por qué."}], "objetivos": ["Identificar aparatos con consumo en espera.", "Estimar su potencia con fuentes confiables.", "Calcular el total mensual.", "Proponer qué hacer con cada uno."], "habilidades": ["Observación.", "Cálculo de energía.", "Búsqueda de especificaciones.", "Comunicación de resultados."], "herramientas": ["Manuales y etiquetas de equipos.", "Hoja de cálculo.", "Medidor enchufable de consumo, si lo tienes."], "lineamientos": ["No desarmes aparatos ni modifiques su conexión: usa únicamente datos de etiqueta o un medidor enchufable.", "No desconectes equipos que necesiten estar encendidos por seguridad o salud, como refrigeradoras o equipos médicos."], "otroSector": "El mismo análisis sirve para estudiar el consumo oculto en una oficina, un laboratorio o un centro de cómputo."}$a26sld$::jsonb,34),
('como-cambia-el-consumo-con-tus-habitos-y-que-ajustar-sin-perder','ambiente',array['sociedad']::text[],'¿Cómo cambia el consumo con tus hábitos y qué ajustar sin perder comodidad?','Registra cómo varía tu consumo de energía según tus horarios y hábitos, y comprueba qué cambios sencillos reducen el gasto sin sacrificar tu comodidad.','Análisis','~25 h',25,array['Energía','Hábitos']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria electrica psicologia economia ingenieria ambiental estadistica ingenieria industrial arquitectura administracion registro sistematico. analisis de datos. diseno de pruebas simples. interpretacion de resultados. hoja de calculo. lectura del medidor, si es accesible. cuaderno de registro.',$a27sld${"id": "como-cambia-el-consumo-con-tus-habitos-y-que-ajustar-sin-perder", "area": "ambiente", "areas2": ["sociedad"], "titulo": "¿Cómo cambia el consumo con tus hábitos y qué ajustar sin perder comodidad?", "resumen": "Registra cómo varía tu consumo de energía según tus horarios y hábitos, y comprueba qué cambios sencillos reducen el gasto sin sacrificar tu comodidad.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Energía", "Hábitos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Eléctrica", "Psicología", "Economía", "Ingeniería Ambiental", "Estadística", "Ingeniería Industrial", "Arquitectura", "Administración"], "problema": ["El consumo de energía cambia según la época, el día de la semana y las costumbres de cada persona. Pero los consejos de ahorro suelen ser generales y no consideran cómo vive cada hogar.", "Por eso muchas recomendaciones no se aplican: piden renunciar a algo que importa. Conocer los patrones propios ayuda a elegir cambios que valen la pena."], "desarrollar": ["Durante dos o tres semanas anota con qué frecuencia usas los principales aparatos, y si puedes, registra la lectura del medidor al empezar y terminar cada día, para ver cómo varía.", "Identifica los tres hábitos que más energía usan, prueba un cambio en cada uno durante una semana, como horario, duración o ajuste, y compara el consumo antes y después con una conclusión honesta."], "ampliaciones": [{"titulo": "Entre semana y fin de semana", "aporta": "compara cómo cambian los patrones entre ambos."}, {"titulo": "Costo de la comodidad", "aporta": "estima cuánto cuesta cada hábito que valoras."}, {"titulo": "Guía personal", "aporta": "arma un resumen de ajustes que funcionaron para ti."}], "objetivos": ["Registrar hábitos y consumo de forma regular.", "Reconocer patrones en los datos.", "Probar cambios y comparar.", "Concluir qué ajustes valen la pena."], "habilidades": ["Registro sistemático.", "Análisis de datos.", "Diseño de pruebas simples.", "Interpretación de resultados."], "herramientas": ["Hoja de cálculo.", "Lectura del medidor, si es accesible.", "Cuaderno de registro."], "lineamientos": ["No bajes tu comodidad o seguridad, por ejemplo con la calefacción, el agua caliente o la refrigeración de alimentos, solo para ahorrar.", "Presenta los resultados como un caso personal: lo que funciona en tu hogar puede no funcionar en otro."], "otroSector": "El mismo enfoque sirve para estudiar cómo cambian el gasto de dinero, el uso del tiempo o el consumo de agua con los hábitos."}$a27sld$::jsonb,35),
('cuanta-energia-consumen-tus-habitos-digitales','ambiente',array['tecnologia']::text[],'¿Cuánta energía consumen tus hábitos digitales?','Estima cuánta energía y carbono hay detrás de ver videos, usar redes, guardar archivos en la nube o tener dispositivos conectados, y qué se puede hacer sin dejar de usarlos.','Investigación','~20 h',20,array['Energía','Tecnología']::text[],array['investigar']::text[],'publicos',NULL,'ingenieria de sistemas ingenieria de software ingenieria electronica ingenieria electrica ciencia de datos fisica comunicaciones ingenieria ambiental investigacion de fuentes. estimacion y orden de magnitud. pensamiento critico. comunicacion de resultados. informes publicos sobre energia digital. hoja de calculo. estadisticas de uso de tu dispositivo.',$a28sld${"id": "cuanta-energia-consumen-tus-habitos-digitales", "area": "ambiente", "areas2": ["tecnologia"], "titulo": "¿Cuánta energía consumen tus hábitos digitales?", "resumen": "Estima cuánta energía y carbono hay detrás de ver videos, usar redes, guardar archivos en la nube o tener dispositivos conectados, y qué se puede hacer sin dejar de usarlos.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Energía", "Tecnología"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ingeniería Electrónica", "Ingeniería Eléctrica", "Ciencia de Datos", "Física", "Comunicaciones", "Ingeniería Ambiental"], "problema": ["Lo digital parece inmaterial, pero cada video, mensaje o archivo guardado requiere servidores, redes y dispositivos que consumen energía. Como no se ve, rara vez se piensa en eso.", "Las cifras que circulan varían mucho según la fuente, y por eso es fácil exagerar o minimizar. Conviene entender cómo se estiman y qué margen de error tienen."], "desarrollar": ["Haz un registro de una semana de tus hábitos digitales, como horas de video, mensajería, juegos y uso de la nube, y busca en fuentes públicas estimaciones de la energía asociada a cada actividad, indicando de dónde salen.", "Calcula un orden de magnitud de tu consumo digital, compara con otros usos de energía de tu vida diaria y propón tres cambios razonables."], "ampliaciones": [{"titulo": "Comparar estimaciones", "aporta": "contrasta lo que dicen distintas fuentes y busca por qué difieren."}, {"titulo": "Dispositivos y redes", "aporta": "separa lo que consume tu dispositivo de lo que consume la red y los servidores."}, {"titulo": "Centros de datos", "aporta": "investiga cómo se reduce el consumo energético de un centro de datos."}], "objetivos": ["Registrar hábitos digitales.", "Buscar estimaciones confiables.", "Calcular un orden de magnitud con sus límites.", "Comunicar con honestidad la incertidumbre."], "habilidades": ["Investigación de fuentes.", "Estimación y orden de magnitud.", "Pensamiento crítico.", "Comunicación de resultados."], "herramientas": ["Informes públicos sobre energía digital.", "Hoja de cálculo.", "Estadísticas de uso de tu dispositivo."], "lineamientos": ["Cita cada estimación y deja claro que son aproximaciones, porque las cifras varían mucho según el método y el año.", "No uses este análisis para culpar a nadie por sus hábitos: sirve para entender dónde está el consumo."], "otroSector": "El mismo método sirve para analizar el consumo de energía y agua de cualquier servicio, desde un sistema de transporte hasta una cadena de supermercados."}$a28sld$::jsonb,36),
('calcula-tu-huella-de-carbono-que-tan-sostenible-es-tu-estilo-de','ambiente',array['ciencias','sociedad']::text[],'Calcula tu huella de carbono: ¿qué tan sostenible es tu estilo de vida?','Calcula con una metodología clara la huella de carbono aproximada de tus actividades cotidianas, transporte, alimentación, energía y consumo, y descubre dónde pesa más.','Análisis','~25 h',25,array['Huella de carbono','Datos']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria ambiental quimica fisica estadistica economia ingenieria industrial administracion educacion calculo con factores de emision. registro de datos. visualizacion de resultados. pensamiento critico. factores de emision publicados. hoja de calculo. registro de actividades de una o dos semanas.',$a29sld${"id": "calcula-tu-huella-de-carbono-que-tan-sostenible-es-tu-estilo-de", "area": "ambiente", "areas2": ["ciencias", "sociedad"], "titulo": "Calcula tu huella de carbono: ¿qué tan sostenible es tu estilo de vida?", "resumen": "Calcula con una metodología clara la huella de carbono aproximada de tus actividades cotidianas, transporte, alimentación, energía y consumo, y descubre dónde pesa más.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Huella de carbono", "Datos"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería Ambiental", "Química", "Física", "Estadística", "Economía", "Ingeniería Industrial", "Administración", "Educación"], "problema": ["Se habla mucho de huella de carbono, pero casi nadie sabe cómo se calcula ni qué parte de su vida pesa más. Las calculadoras en línea dan números distintos y no explican por qué.", "Entender el cálculo permite saber qué actividades concentran la mayor parte y cuáles cambios importan realmente."], "desarrollar": ["Elige un método público y documentado para estimar tu huella, registra durante una o dos semanas tus desplazamientos, tu uso de energía, tu alimentación y tus compras, y calcula tu huella con factores de emisión citados.", "Muestra en un gráfico qué categorías pesan más, explica qué supuestos usaste y qué datos fueron estimaciones, y propón dos cambios con su efecto estimado."], "ampliaciones": [{"titulo": "Comparar calculadoras", "aporta": "contrasta el resultado de dos calculadoras y explica las diferencias."}, {"titulo": "Datos por categoría", "aporta": "profundiza en la categoría que más pesa en tu caso."}, {"titulo": "Escenarios", "aporta": "simula cómo cambiaría tu huella si hicieras tres cambios distintos."}], "objetivos": ["Elegir una metodología confiable.", "Registrar datos de actividades.", "Aplicar factores de emisión citados.", "Interpretar y comunicar los resultados."], "habilidades": ["Cálculo con factores de emisión.", "Registro de datos.", "Visualización de resultados.", "Pensamiento crítico."], "herramientas": ["Factores de emisión publicados.", "Hoja de cálculo.", "Registro de actividades de una o dos semanas."], "lineamientos": ["Cita la fuente de cada factor de emisión y aclara que tu resultado es una estimación personal, no una medida exacta.", "Evita compararte con otras personas o culparte: el objetivo es entender, no medir virtud."], "otroSector": "El mismo cálculo sirve para estimar la huella de un evento, una empresa, una facultad o un producto."}$a29sld$::jsonb,37),
('tu-plan-de-30-dias-para-reducir-tu-huella','ambiente',array['sociedad']::text[],'Tu plan de 30 días para reducir tu huella','Diseña y prueba un plan realista de un mes con pequeños cambios en tu vida diaria, mide qué lograste y ajusta lo que no funcionó, sin perfeccionismo.','Plan','1 mes',30,array['Plan personal','Hábitos']::text[],array['resolver','crear']::text[],'propios',NULL,'psicologia ingenieria ambiental educacion administracion comunicaciones economia estadistica ingenieria industrial planificacion. seguimiento de indicadores. autoevaluacion honesta. comunicacion de resultados. hoja de calculo o cuaderno. una aplicacion de seguimiento de habitos. un editor de graficos.',$a30sld${"id": "tu-plan-de-30-dias-para-reducir-tu-huella", "area": "ambiente", "areas2": ["sociedad"], "titulo": "Tu plan de 30 días para reducir tu huella", "resumen": "Diseña y prueba un plan realista de un mes con pequeños cambios en tu vida diaria, mide qué lograste y ajusta lo que no funcionó, sin perfeccionismo.", "tipo": "Plan", "tiempo": "1 mes", "horas": 30, "etiquetas": ["Plan personal", "Hábitos"], "intencion": ["resolver", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Psicología", "Ingeniería Ambiental", "Educación", "Administración", "Comunicaciones", "Economía", "Estadística", "Ingeniería Industrial"], "problema": ["Los propósitos ambientales suelen empezar con entusiasmo y terminar en una semana porque piden demasiado de golpe. Sin medir ni ajustar, es difícil saber si el cambio valió la pena.", "Un plan con pocos cambios, medidos y con margen para fallar tiene más posibilidades de convertirse en costumbre."], "desarrollar": ["Elige tres cambios concretos en áreas distintas, como transporte, residuos y consumo, define cómo medirás cada uno y registra tu línea base durante una semana.", "Aplica los cambios durante cuatro semanas, anota cada semana qué pasó, compara con tu línea base y termina con un balance: qué mantendrías, qué descartarías y por qué."], "ampliaciones": [{"titulo": "Hacerlo en pareja", "aporta": "propón el plan a otra persona y compara cómo les fue."}, {"titulo": "Tablero de seguimiento", "aporta": "crea un tablero visual con tus indicadores semanales."}, {"titulo": "Costo y ahorro", "aporta": "calcula si el plan te cuesta o te ahorra dinero."}], "objetivos": ["Elegir cambios realistas.", "Medir antes y durante.", "Reflexionar sobre los resultados.", "Decidir qué hábitos mantener."], "habilidades": ["Planificación.", "Seguimiento de indicadores.", "Autoevaluación honesta.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo o cuaderno.", "Una aplicación de seguimiento de hábitos.", "Un editor de gráficos."], "lineamientos": ["No adoptes cambios que afecten tu salud, tu seguridad o tu economía; el plan debe ser sostenible.", "Presenta el resultado como aprendizaje personal, aunque no hayas logrado todo."], "otroSector": "El mismo esquema sirve para planes de estudio, de ahorro, de ejercicio o de organización del tiempo."}$a30sld$::jsonb,38)
